H.background();
const w = H.W, hh = H.H;
const s = P.s;
const a11 = P.a, b11 = P.b;
const A = [[a11, 2], [-1, 3]];
const B = [[b11, 1], [4, -2]];
const phase = (t * 0.4) % 3;
const showSum = phase < 1.5;
const Csum = [[A[0][0] + B[0][0], A[0][1] + B[0][1]], [A[1][0] + B[1][0], A[1][1] + B[1][1]]];
const Cscl = [[s * A[0][0], s * A[0][1]], [s * A[1][0], s * A[1][1]]];
function drawMat(M, x, y, label, hot) {
  const cw = 46, ch = 34;
  H.rect(x - 8, y - 24, cw * 2 + 16, ch * 2 + 8, { stroke: H.colors.grid, width: 2, radius: 8 });
  H.text(label, x - 6, y - 32, { color: H.colors.ink, size: 15, weight: 700 });
  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 2; c++) {
      const cx = x + c * cw, cy = y + r * ch;
      const isHot = hot && r === 0 && c === 0;
      H.text(M[r][c].toFixed(1), cx + 14, cy + 6, { color: isHot ? H.colors.warn : H.colors.sub, size: 16, align: "center" });
    }
  }
}
const baseY = hh * 0.42;
drawMat(A, w * 0.07, baseY, "A", true);
H.text(showSum ? "+" : "*", w * 0.30, baseY + 18, { color: H.colors.accent2, size: 26, weight: 700 });
if (showSum) {
  drawMat(B, w * 0.35, baseY, "B", true);
} else {
  H.text(s.toFixed(1), w * 0.355, baseY + 18, { color: H.colors.good, size: 22, weight: 700 });
}
H.text("=", w * 0.62, baseY + 18, { color: H.colors.ink, size: 26, weight: 700 });
const pulse = 6 + 4 * Math.abs(Math.sin(t * 2));
H.circle(w * 0.70 + 30, baseY + 8, pulse, { stroke: H.colors.warn, width: 2 });
drawMat(showSum ? Csum : Cscl, w * 0.70, baseY, showSum ? "A + B" : (s.toFixed(1) + "*A"), true);
H.text("Matrix add & scalar multiply", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text(showSum
  ? "Add entry-by-entry:  a11+b11 = " + A[0][0].toFixed(1) + " + " + B[0][0].toFixed(1) + " = " + Csum[0][0].toFixed(1)
  : "Scale every entry by " + s.toFixed(1) + ":  " + s.toFixed(1) + "*" + A[0][0].toFixed(1) + " = " + Cscl[0][0].toFixed(1),
  24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: showSum ? "sum (A+B)" : "scaled (s*A)", color: H.colors.warn }], w - 170, 28);
